insert into public.quests (questline_id, key, position, name, level_required, giver_external_id, summary, wait_for_npc_turn_in, status, source_path, source_metadata) values ((select id from public.questlines where key = 'adjectives_basics_homework'), 'adjectives_basics_homework__q01_the_gift_painting', 0, 'The Gift Painting', 50, 'Painter', 'הילדה מהפארק תקבל ציור במתנה, והוא ייצא בדיוק כמו המילים שלכם. הראו לבד שאתם זוכרים את מילות התיאור ואיפה הן עומדות במשפט.', true, 'complete', 'questlines\adjectives_basics_homework\adjectives_basics_homework__q01_the_gift_painting.yaml', '{"source_detail":{"giver_npc":"Painter","id":"adjectives_basics_homework__q01_the_gift_painting","level_required":50,"name":"The Gift Painting","prerequisite":null,"summary":"הילדה מהפארק תקבל ציור במתנה, והוא ייצא בדיוק כמו המילים שלכם. הראו לבד שאתם זוכרים את מילות התיאור ואיפה הן עומדות במשפט.","turn_in_dialogue_id":"adjectives_basics_homework_q01_finish","wait_for_npc_turn_in":true},"source_index_path":"questlines\\adjectives_basics_homework\\_index.yaml"}'::jsonb) on conflict (questline_id, key) do update set position = excluded.position, name = excluded.name, level_required = excluded.level_required, giver_external_id = excluded.giver_external_id, summary = excluded.summary, wait_for_npc_turn_in = excluded.wait_for_npc_turn_in, status = excluded.status, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
